-- Listage de la structure de la base pour sigom
CREATE DATABASE IF NOT EXISTS `sigom` /*!40100 DEFAULT CHARACTER SET latin1 */ /*!80016 DEFAULT ENCRYPTION='N' */;
USE `sigom`;

-- Listage de la structure de la table sigom. agents
CREATE TABLE IF NOT EXISTS `agents` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `matricule` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `prenom` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nom` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `poste` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fonction` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `categorie` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `service` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `agents_matricule_unique` (`matricule`),
  KEY `agents_service_foreign` (`service`),
  KEY `agents_fonction_id_foreign` (`fonction`),
  KEY `agents_categorie_id_foreign` (`categorie`),
  CONSTRAINT `agents_categorie_id_foreign` FOREIGN KEY (`categorie`) REFERENCES `categories` (`nom_categorie`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `agents_fonction_id_foreign` FOREIGN KEY (`fonction`) REFERENCES `fonctions` (`nom_fonction`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `agents_service_foreign` FOREIGN KEY (`service`) REFERENCES `services` (`nom_service`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=390 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

