-- Listage de la structure de la table sigom. fonctions
CREATE TABLE IF NOT EXISTS `fonctions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nom_fonction` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `categorie_id` bigint unsigned DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `fonctions_nom_fonction_unique` (`nom_fonction`),
  KEY `idx_fonctions_categorie_id` (`categorie_id`),
  CONSTRAINT `fk_fonctions_categorie` FOREIGN KEY (`categorie_id`) REFERENCES `categories` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

