-- Listage de la structure de la table sigom. missions
CREATE TABLE IF NOT EXISTS `missions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `numero` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `objet` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `direction` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chauffeur_id` int unsigned DEFAULT NULL,
  `type` enum('nationale','internationale') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `pays_id` bigint unsigned DEFAULT NULL,
  `region_id` bigint unsigned DEFAULT NULL,
  `voiture_id` bigint unsigned DEFAULT NULL,
  `date_affectation_voiture` date DEFAULT NULL,
  `observation_moyens_generaux` text COLLATE utf8mb4_unicode_ci,
  `destination` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date_depart` date NOT NULL,
  `date_retour` date NOT NULL,
  `duree` int DEFAULT NULL,
  `statut` enum('brouillon','en_attente_cg','en_cours_cg','en_attente_service_demandeur','en_attente_visa_dga','en_attente_visa_dagrh','en_attente_mg','en_attente_rh','en_attente_budget','en_attente_comptabilite','payee','terminee','annulee') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'brouillon',
  `montant_total` decimal(15,2) NOT NULL DEFAULT '0.00',
  `montant_complementaire_international` decimal(15,2) NOT NULL DEFAULT '0.00',
  `montant_carburant` decimal(15,2) NOT NULL DEFAULT '0.00',
  `montant_total_general` decimal(15,2) NOT NULL DEFAULT '0.00',
  `date_paiement` date DEFAULT NULL,
  `reference_paiement` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `montant_paye` decimal(15,2) NOT NULL DEFAULT '0.00',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `mission_initiation_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `missions_numero_unique` (`numero`),
  UNIQUE KEY `uq_missions_mission_initiation_id` (`mission_initiation_id`),
  KEY `missions_pays_id_foreign` (`pays_id`),
  KEY `missions_region_id_foreign` (`region_id`),
  KEY `missions_voiture_id_index` (`voiture_id`),
  KEY `missions_direction_foreign` (`direction`),
  KEY `missions_chauffeur_id_foreign` (`chauffeur_id`),
  CONSTRAINT `fk_missions_mission_initiation` FOREIGN KEY (`mission_initiation_id`) REFERENCES `mission_initiations` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `missions_chauffeur_id_foreign` FOREIGN KEY (`chauffeur_id`) REFERENCES `agents` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `missions_direction_foreign` FOREIGN KEY (`direction`) REFERENCES `directions` (`nom_direction`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `missions_pays_id_foreign` FOREIGN KEY (`pays_id`) REFERENCES `pays` (`id`) ON DELETE SET NULL,
  CONSTRAINT `missions_region_id_foreign` FOREIGN KEY (`region_id`) REFERENCES `regions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `missions_voiture_id_foreign` FOREIGN KEY (`voiture_id`) REFERENCES `voitures` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

