-- Listage de la structure de la table sigom. voitures
CREATE TABLE IF NOT EXISTS `voitures` (
  `id` bigint unsigned NOT NULL DEFAULT '0',
  `immatriculation` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `marque` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `modele` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `annee` year DEFAULT NULL,
  `couleur` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `type_carburant` enum('essence','diesel') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'diesel',
  `kilometrage` int unsigned NOT NULL DEFAULT '0',
  `etat` enum('bon','moyen','mauvais','hors_service') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'bon',
  `disponible` tinyint(1) NOT NULL DEFAULT '1',
  `date_mise_service` date DEFAULT NULL,
  `observation` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `voitures_immatriculation_unique` (`immatriculation`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

